using Nexcore.SharedKernel;
using Sales.Domain.Enums;

namespace Sales.Domain.Entities;

/// <summary>
/// Outbound Delivery / Shipment document.
/// Aligned with SAP VL01N Outbound Delivery, Oracle Shipment, Dynamics Shipment.
/// Triggers inventory deduction in the Inventory module.
/// </summary>
public class Delivery : BaseEntity
{
    // ??? Identity ?????????????????????????????????????????????????????????????
    /// <summary>Auto-generated delivery number (e.g., DN-2024-00001).</summary>
    public string DeliveryNumber { get; set; } = string.Empty;

    // ??? Source Order ?????????????????????????????????????????????????????????
    public Guid SalesOrderId { get; set; }
    public SalesOrder SalesOrder { get; set; } = null!;

    /// <summary>Cross-module reference to Crm.Contact. ID only.</summary>
    public Guid? ContactId { get; set; }
    /// <summary>Snapshot of contact name for fast reads.</summary>
    public string? ContactName { get; set; }

    // ??? Status ???????????????????????????????????????????????????????????????
    public DeliveryStatus Status { get; set; } = DeliveryStatus.Draft;

    // ??? Dates ????????????????????????????????????????????????????????????????
    public DateTime PlannedDeliveryDate { get; set; }
    public DateTime? ActualShipDate { get; set; }
    public DateTime? ActualDeliveryDate { get; set; }

    // ??? Shipping ?????????????????????????????????????????????????????????????
    public string? Carrier { get; set; }
    public string? ShippingMethod { get; set; }
    public string? TrackingNumber { get; set; }
    public Incoterm? Incoterm { get; set; }
    public string? IncotermLocation { get; set; }

    // ??? Source Warehouse ?????????????????????????????????????????????????????
    public Guid? WarehouseId { get; set; }    // FK to Inventory Warehouse

    // ── Delivery Address ─────────────────────────────────────────────────────
    public string? RecipientName { get; set; }
    public string? RecipientPhone { get; set; }
    public string? RecipientWhatsApp { get; set; }
    public string? Street { get; set; }
    public string? City { get; set; }
    public string? State { get; set; }
    public string? PostalCode { get; set; }
    public string? Country { get; set; }

    // ── GPS Coordinates ──────────────────────────────────────────────────────
    public double? DeliveryLatitude { get; set; }
    public double? DeliveryLongitude { get; set; }

    // ── Delivery Notes ───────────────────────────────────────────────────────
    /// <summary>Customer-facing instructions shown to the rider (e.g. "Ring bell, 2nd floor").</summary>
    public string? DeliveryNotes { get; set; }

    // ── Assigned Rider ───────────────────────────────────────────────────────
    /// <summary>
    /// Rider directly assigned to execute this delivery.
    /// Use RiderAssignment for the full dispatch lifecycle (accept, pickup, deliver, fail).
    /// </summary>
    public Guid? AssignedRiderId { get; set; }
    public Rider? AssignedRider { get; set; }
    /// <summary>Snapshot of rider display name for fast reads without a join.</summary>
    public string? RiderName { get; set; }

    // ── Packaging ────────────────────────────────────────────────────────────
    public int? NumberOfPackages { get; set; }
    public decimal? TotalWeight { get; set; }
    public string? WeightUnit { get; set; }
    public decimal? TotalVolume { get; set; }
    public string? VolumeUnit { get; set; }

    public string? Notes { get; set; }

    // ── Navigation ───────────────────────────────────────────────────────────
    public ICollection<DeliveryLine> Lines { get; set; } = new List<DeliveryLine>();
    public ICollection<DeliveryPackage> Packages { get; set; } = new List<DeliveryPackage>();
}
